package com.yihe.framework.ehr;
import java.util.*;
import java.time.LocalDate;
import java.io.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.core.io.ClassPathResource;
import static com.yihe.framework.ehr.EhrAccess.*;
import static com.yihe.framework.ehr.EhrService.*;

/** Tenant-scoped editorial drafts, immutable published snapshots and local lexical retrieval. */
@Service
public class ServiceKnowledge {
 final EhrRepository db;final EhrService ehr;
 public ServiceKnowledge(EhrRepository db,EhrService ehr){this.db=db;this.ehr=ehr;}
 static boolean flag(Object x){return Boolean.TRUE.equals(x)||(x instanceof Number&&((Number)x).intValue()==1);}
 void staff(EhrActor a){require(!a.mobile,403,"知识库管理仅供后台人员使用");}
 @SuppressWarnings("unchecked") Map<String,Object> json(Object x){return (Map<String,Object>)ehr.decode(x);}
 @SuppressWarnings("unchecked") List<Object> array(Object x){return (List<Object>)ehr.decode(x);}
 Map<String,Object> owned(EhrActor a,String id,boolean lock){staff(a);Map<String,Object> r=db.one("SELECT * FROM a_service_kb_documents WHERE document_id=? AND scope_code=? AND data_mode=? AND deleted_at IS NULL"+(lock?" FOR UPDATE":""),CommunicationService.uuid(id),a.scope,a.mode);require(r!=null,404,"知识不存在或无权访问");return r;}
 void version(Map<String,Object> row,Map<String,Object> b){require(num(row.get("row_version"))==num(b.get("version")),409,"内容已被其他人修改，请刷新后重试");}
 List<Map<String,Object>> categories(EhrActor a){staff(a);return db.all("SELECT c.category_id id,c.code,c.name,c.sort_order sort,c.row_version version,COUNT(d.document_id) count FROM a_service_kb_categories c LEFT JOIN a_service_kb_documents d ON d.category_id=c.category_id AND d.deleted_at IS NULL WHERE c.scope_code=? AND c.data_mode=? GROUP BY c.category_id ORDER BY c.sort_order,c.code",a.scope,a.mode);}
 Map<String,Object> category(EhrActor a,String cid){Map<String,Object> c=db.one("SELECT * FROM a_service_kb_categories WHERE category_id=? AND scope_code=? AND data_mode=?",cid,a.scope,a.mode);require(c!=null,422,"分类不存在");return c;}
 @Transactional public Map<String,Object> saveCategory(EhrActor a,String cid,Map<String,Object>b){staff(a);String name=ehr.safe(b,"name",80);require(!name.isEmpty(),422,"请填写分类名称");int sort=num(b.get("sort"));require(sort>=0&&sort<=999,422,"排序范围0至999");if(cid==null){cid=id();require(categories(a).size()<30,422,"最多30个分类");db.insert("a_service_kb_categories",map("category_id",cid,"scope_code",a.scope,"data_mode",a.mode,"code","custom_"+id().substring(0,8),"name",name,"sort_order",sort));}else{Map<String,Object> c=category(a,cid);version(c,b);db.exec("UPDATE a_service_kb_categories SET name=?,sort_order=?,row_version=row_version+1 WHERE category_id=? AND row_version=?",name,sort,cid,c.get("row_version"));}return map("categories",categories(a));}
 @Transactional public void deleteCategory(EhrActor a,String cid,int revision){staff(a);Map<String,Object> c=category(a,cid);require(num(c.get("row_version"))==revision,409,"分类已变化");require(db.count("SELECT COUNT(*) FROM a_service_kb_documents WHERE category_id=?",cid)==0,409,"分类已有文档或历史记录，请先移走文档；含历史记录的分类可更名保留");db.exec("DELETE FROM a_service_kb_categories WHERE category_id=?",cid);}
 @SuppressWarnings("unchecked") Map<String,Object> normalized(EhrActor a,Map<String,Object>b){String cid=text(b,"categoryId");category(a,cid);String title=ehr.safe(b,"title",180),body=ehr.safe(b,"body",30000),kind=text(b,"kind");require(!title.isEmpty()&&body.length()>=30,422,"标题必填，正文至少30字");require(Arrays.asList("reference","template","platform").contains(kind),422,"资料性质无效");List<String> keys=new AutoReplyRules(db,ehr).strings(b.get("keywords"),20,50,"关键词");require(b.get("sources") instanceof List,422,"请提供来源数组");List<Map<String,Object>> sources=new ArrayList<>();for(Object raw:(List<?>)b.get("sources")){require(raw instanceof Map,422,"来源格式错误");Map<String,Object> x=(Map<String,Object>)raw;String name=ehr.safe(x,"name",180),url=ehr.safe(x,"url",600),date=ehr.safe(x,"date",30);require(!name.isEmpty(),422,"来源名称必填");if(!url.isEmpty())try{java.net.URI u=java.net.URI.create(url);require("https".equals(u.getScheme())&&u.getHost()!=null&&u.getUserInfo()==null,422,"来源链接须为HTTPS");}catch(IllegalArgumentException e){throw new EhrException(422,"来源链接无效");}sources.add(map("name",name,"url",url,"date",date));}require(!sources.isEmpty()&&sources.size()<=8,422,"每篇需1至8个来源");String expires=text(b,"expiresOn");if(!expires.isEmpty())try{LocalDate.parse(expires);}catch(Exception e){throw new EhrException(422,"到期日格式为YYYY-MM-DD");}require(b.get("aiEnabled") instanceof Boolean&&b.get("adopted") instanceof Boolean,422,"AI检索与企业采纳状态须为布尔值");return map("categoryId",cid,"title",title,"body",body,"kind",kind,"keywords",keys,"sources",sources,"aiEnabled",b.get("aiEnabled"),"adopted",b.get("adopted"),"expiresOn",expires);}
 Map<String,Object> document(Map<String,Object>r,boolean full){Map<String,Object> d=map("id",r.get("document_id"),"categoryId",r.get("category_id"),"title",r.get("title"),"keywords",array(r.get("keywords")),"kind",r.get("content_kind"),"status",r.get("document_status"),"aiEnabled",flag(r.get("ai_enabled")),"adopted",flag(r.get("adopted")),"version",r.get("row_version"),"updatedAt",r.get("updated_at"),"expiresOn",r.get("expires_on"));Map<String,Object> live=r.get("published_json")==null?null:json(r.get("published_json"));d.put("publishedVersion",live==null?null:live.get("revision"));d.put("hasUnpublishedChanges",live!=null&&num(live.get("revision"))<num(r.get("row_version")));if(full){d.put("body",r.get("body_text"));d.put("sources",array(r.get("sources_json")));d.put("published",live);}return d;}
 void audit(EhrActor a,Map<String,Object>row,String action){db.insert("a_service_kb_versions",map("version_id",id(),"document_id",row.get("document_id"),"revision",row.get("row_version"),"action_name",action,"snapshot_json",ehr.encode(document(row,true)),"actor_user",a.user,"created_at",now()));}
 void write(String did,Map<String,Object>d,String actor){db.exec("UPDATE a_service_kb_documents SET category_id=?,title=?,keywords=?,body_text=?,sources_json=?,content_kind=?,ai_enabled=?,adopted=?,expires_on=?,updated_by=?,row_version=row_version+1,updated_at=UTC_TIMESTAMP(6) WHERE document_id=?",d.get("categoryId"),d.get("title"),ehr.encode(d.get("keywords")),d.get("body"),ehr.encode(d.get("sources")),d.get("kind"),d.get("aiEnabled"),d.get("adopted"),str(d.get("expiresOn")).isEmpty()?null:d.get("expiresOn"),actor,did);}
 @Transactional public Map<String,Object> save(EhrActor a,String did,Map<String,Object>b){staff(a);Map<String,Object>d=normalized(a,b);if(did==null){did=id();db.insert("a_service_kb_documents",map("document_id",did,"scope_code",a.scope,"data_mode",a.mode,"category_id",d.get("categoryId"),"title",d.get("title"),"keywords",ehr.encode(d.get("keywords")),"body_text",d.get("body"),"sources_json",ehr.encode(d.get("sources")),"content_kind",d.get("kind"),"ai_enabled",d.get("aiEnabled"),"adopted",d.get("adopted"),"expires_on",str(d.get("expiresOn")).isEmpty()?null:d.get("expiresOn"),"updated_by",a.user,"created_at",now(),"updated_at",now()));}else{Map<String,Object>row=owned(a,did,true);version(row,b);write(did,d,a.user);}Map<String,Object> row=owned(a,did,false);audit(a,row,"save");return document(row,true);}
 public Map<String,Object> detail(EhrActor a,String did){return document(owned(a,did,false),true);}
 public List<Map<String,Object>> history(EhrActor a,String did){owned(a,did,false);return db.all("SELECT version_id id,revision,action_name action,actor_user actor,created_at time FROM a_service_kb_versions WHERE document_id=? ORDER BY revision DESC LIMIT 100",did);}
 @Transactional public Map<String,Object> restore(EhrActor a,String did,Map<String,Object>b){version(owned(a,did,true),b);Map<String,Object> v=db.one("SELECT snapshot_json FROM a_service_kb_versions WHERE document_id=? AND version_id=?",did,text(b,"versionId"));require(v!=null,404,"历史版本不存在");Map<String,Object>snapshot=json(v.get("snapshot_json"));snapshot.put("version",b.get("version"));return save(a,did,snapshot);}
 @Transactional public Map<String,Object> action(EhrActor a,String did,Map<String,Object>b){Map<String,Object> row=owned(a,did,true);version(row,b);String action=text(b,"action");require(Arrays.asList("publish","archive","delete","copy").contains(action),422,"操作无效");if(action.equals("copy")){Map<String,Object>d=document(row,true);d.put("title",str(d.get("title"))+"（副本）");d.put("adopted",false);return save(a,null,d);}if(action.equals("publish")){Map<String,Object>d=normalized(a,document(row,true));require(!"template".equals(d.get("kind"))||Boolean.TRUE.equals(d.get("adopted")),422,"参考模板须经企业核实采纳后才能发布");String expiry=str(d.get("expiresOn"));require(expiry.isEmpty()||!LocalDate.parse(expiry).isBefore(LocalDate.now(java.time.ZoneId.of("Asia/Shanghai"))),422,"资料已过期，请更新有效期");d.put("id",did);d.put("revision",num(row.get("row_version"))+1);db.exec("UPDATE a_service_kb_documents SET document_status='published',published_json=?,row_version=row_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE document_id=?",ehr.encode(d),a.user,did);}else db.exec("UPDATE a_service_kb_documents SET document_status=?,deleted_at="+(action.equals("delete")?"UTC_TIMESTAMP(6)":"NULL")+",row_version=row_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE document_id=?",action.equals("archive")?"archived":"draft",a.user,did);Map<String,Object> after=db.one("SELECT * FROM a_service_kb_documents WHERE document_id=?",did);audit(a,after,action);return document(after,true);}
 @Transactional public Map<String,Object> batch(EhrActor a,Map<String,Object>b){staff(a);require(b.get("items") instanceof List,422,"请选择文档及版本");List<?> list=(List<?>)b.get("items");require(!list.isEmpty()&&list.size()<=500,422,"一次选择1至500篇");List<Map<String,Object>> out=new ArrayList<>();Set<String> seen=new HashSet<>();for(Object raw:list){require(raw instanceof Map,422,"文档格式错误");Map<?,?>x=(Map<?,?>)raw;String did=str(x.get("id"));require(seen.add(did),422,"文档重复");out.add(action(a,did,map("version",x.get("version"),"action",b.get("action"))));}return map("count",out.size());}
 public Map<String,Object> list(EhrActor a,Map<String,String>q){staff(a);int page=Math.max(1,Math.min(10000,parse(q.get("page"),1))),size=Math.max(1,Math.min(100,parse(q.get("size"),10)));String sql=" FROM a_service_kb_documents WHERE scope_code=? AND data_mode=? AND deleted_at IS NULL";List<Object> args=new ArrayList<>(Arrays.asList(a.scope,a.mode));for(String key:Arrays.asList("categoryId","status","kind")){String val=q.get(key);if(val!=null&&!val.isEmpty()){sql+=" AND "+(key.equals("categoryId")?"category_id":key.equals("status")?"document_status":"content_kind")+"=?";args.add(val);}}String search=q.getOrDefault("search","").trim();require(search.length()<=100,422,"搜索词过长");if(!search.isEmpty()){String term="%"+search.replace("!","!!").replace("%","!%").replace("_","!_")+"%";sql+=" AND (title LIKE ? ESCAPE '!' OR CAST(keywords AS CHAR) LIKE ? ESCAPE '!' OR body_text LIKE ? ESCAPE '!')";args.add(term);args.add(term);args.add(term);}long total=db.count("SELECT COUNT(*)"+sql,args.toArray());List<Object> params=new ArrayList<>(args);params.add(size);params.add((page-1)*size);List<Map<String,Object>> rows=db.all("SELECT *"+sql+" ORDER BY updated_at DESC,document_id LIMIT ? OFFSET ?",params.toArray());List<Object>items=new ArrayList<>();for(Map<String,Object>r:rows)items.add(document(r,false));return map("items",items,"total",total,"page",page,"size",size,"categories",categories(a),"statistics",statistics(a));}
 static int parse(String s,int fallback){try{return Integer.parseInt(s);}catch(Exception e){return fallback;}}
 public Map<String,Object> statistics(EhrActor a){staff(a);Map<String,Object> s=db.one("SELECT COUNT(*) total,COALESCE(SUM(document_status='published'),0) published,COALESCE(SUM(document_status='draft'),0) drafts,COALESCE(SUM(document_status='archived'),0) archived,COALESCE(SUM(updated_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)),0) recent FROM a_service_kb_documents WHERE scope_code=? AND data_mode=? AND deleted_at IS NULL",a.scope,a.mode);s.put("citations",db.count("SELECT COUNT(*) FROM a_service_kb_usage WHERE scope_code=? AND data_mode=?",a.scope,a.mode));s.put("usage",db.all("SELECT c.name,c.category_id id,COUNT(*) count FROM a_service_kb_usage u JOIN a_service_kb_documents d ON d.document_id=u.document_id JOIN a_service_kb_categories c ON c.category_id=d.category_id WHERE u.scope_code=? AND u.data_mode=? AND u.created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY) GROUP BY c.category_id ORDER BY count DESC",a.scope,a.mode));s.put("top",db.all("SELECT d.document_id id,d.title,COUNT(*) count FROM a_service_kb_usage u JOIN a_service_kb_documents d ON d.document_id=u.document_id WHERE u.scope_code=? AND u.data_mode=? AND u.created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY) GROUP BY d.document_id ORDER BY count DESC LIMIT 5",a.scope,a.mode));return s;}
 public Map<String,Object> settings(EhrActor a){staff(a);Map<String,Object> c=db.one("SELECT enabled,top_k topK,min_score minScore,category_ids categoryIds,row_version version FROM a_service_kb_settings WHERE scope_code=? AND data_mode=?",a.scope,a.mode);if(c==null)return map("enabled",false,"topK",4,"minScore",18,"categoryIds",Collections.emptyList(),"version",0);c.put("categoryIds",c.get("categoryIds")==null?Collections.emptyList():array(c.get("categoryIds")));return c;}
 @Transactional public Map<String,Object> configure(EhrActor a,Map<String,Object>b){staff(a);Map<String,Object> row=db.one("SELECT * FROM a_service_kb_settings WHERE scope_code=? AND data_mode=? FOR UPDATE",a.scope,a.mode);require(row!=null,409,"请先载入资料库");version(row,b);int k=num(b.get("topK")),score=num(b.get("minScore"));require(b.get("enabled") instanceof Boolean&&k>=1&&k<=8&&score>=1&&score<=100,422,"检索配置无效");List<String> cats=new AutoReplyRules(db,ehr).strings(b.get("categoryIds"),30,36,"分类范围");for(String cid:cats)category(a,cid);db.exec("UPDATE a_service_kb_settings SET enabled=?,top_k=?,min_score=?,category_ids=?,row_version=row_version+1,updated_at=UTC_TIMESTAMP(6) WHERE scope_code=? AND data_mode=?",b.get("enabled"),k,score,ehr.encode(cats),a.scope,a.mode);return settings(a);}
 @SuppressWarnings("unchecked") public List<Map<String,Object>> retrieve(EhrActor a,String question){staff(a);Map<String,Object>setting=settings(a);if(!flag(setting.get("enabled")))return Collections.emptyList();String q=question.toLowerCase(Locale.ROOT).replaceAll("\\s+","");require(q.length()<=2000,422,"检索问题过长");Set<String>grams=new HashSet<>();for(int i=0;i+1<q.length();i++)grams.add(q.substring(i,i+2));List<Map<String,Object>>out=new ArrayList<>();for(Map<String,Object>r:db.all("SELECT document_id,published_json FROM a_service_kb_documents WHERE scope_code=? AND data_mode=? AND deleted_at IS NULL AND document_status='published' AND published_json IS NOT NULL",a.scope,a.mode)){Map<String,Object>d=json(r.get("published_json"));if(!Boolean.TRUE.equals(d.get("aiEnabled")))continue;if(!((List<?>)setting.get("categoryIds")).isEmpty()&&!((List<?>)setting.get("categoryIds")).contains(d.get("categoryId")))continue;String expiry=str(d.get("expiresOn"));if(!expiry.isEmpty()&&LocalDate.parse(expiry).isBefore(LocalDate.now(java.time.ZoneId.of("Asia/Shanghai"))))continue;String title=str(d.get("title")).toLowerCase(Locale.ROOT),keys=String.valueOf(d.get("keywords")).toLowerCase(Locale.ROOT);int hits=0;for(String gram:grams)if(title.contains(gram)||keys.contains(gram))hits++;double score=grams.isEmpty()?0:100.0*hits/grams.size();for(Object key:(List<?>)d.get("keywords"))if(q.contains(str(key).toLowerCase(Locale.ROOT)))score=Math.max(score,65);if(score<num(setting.get("minScore")))continue;String body=str(d.get("body"));out.add(map("id",r.get("document_id"),"title",d.get("title"),"content",body.substring(0,Math.min(3500,body.length())),"sources",d.get("sources"),"revision",d.get("revision"),"score",Math.round(score),"source","service_knowledge"));}out.sort((x,y)->Integer.compare(num(y.get("score")),num(x.get("score"))));return new ArrayList<>(out.subList(0,Math.min(num(setting.get("topK")),out.size())));}
 public void recordUsage(EhrActor a,List<Map<String,Object>>refs,String key,String channel){for(Map<String,Object>r:refs){if(!"service_knowledge".equals(r.get("source")))continue;db.exec("INSERT IGNORE INTO a_service_kb_usage(usage_id,document_id,scope_code,data_mode,request_key,channel_name,revision,created_at) SELECT ?,document_id,scope_code,data_mode,?,?,?,UTC_TIMESTAMP(6) FROM a_service_kb_documents WHERE document_id=? AND scope_code=? AND data_mode=? AND deleted_at IS NULL AND document_status='published' AND JSON_EXTRACT(published_json,'$.revision')=?",id(),key,channel,r.get("revision"),r.get("id"),a.scope,a.mode,r.get("revision"));}}
 @SuppressWarnings("unchecked") @Transactional public Map<String,Object> initialize(EhrActor a){staff(a);Map<String,Object> seed;try(InputStream in=new ClassPathResource("ehr/service-knowledge-seed.json").getInputStream()){seed=new ObjectMapper().readValue(in,Map.class);}catch(IOException ex){throw new IllegalStateException("Knowledge seed unavailable",ex);}db.exec("INSERT IGNORE INTO a_service_kb_settings(scope_code,data_mode,updated_at) VALUES(?,?,UTC_TIMESTAMP(6))",a.scope,a.mode);db.one("SELECT * FROM a_service_kb_settings WHERE scope_code=? AND data_mode=? FOR UPDATE",a.scope,a.mode);Map<String,String>cats=new HashMap<>();for(Map<String,Object> c:categories(a))cats.put(str(c.get("code")),str(c.get("id")));for(Map<String,Object>c:(List<Map<String,Object>>)seed.get("categories"))if(!cats.containsKey(c.get("code"))){String cid=id();db.insert("a_service_kb_categories",map("category_id",cid,"scope_code",a.scope,"data_mode",a.mode,"code",c.get("code"),"name",c.get("name"),"sort_order",c.get("sort")));cats.put(str(c.get("code")),cid);}Set<String>exists=new HashSet<>();for(Map<String,Object>d:db.all("SELECT seed_key FROM a_service_kb_documents WHERE scope_code=? AND data_mode=?",a.scope,a.mode))exists.add(str(d.get("seed_key")));int added=0;for(Map<String,Object>raw:(List<Map<String,Object>>)seed.get("documents")){if(exists.contains(raw.get("seedKey")))continue;Map<String,Object>b=new LinkedHashMap<>(raw);b.put("categoryId",cats.get(b.get("categoryCode")));Map<String,Object>d=save(a,null,b);db.exec("UPDATE a_service_kb_documents SET seed_key=? WHERE document_id=?",b.get("seedKey"),d.get("id"));if(!"template".equals(b.get("kind")))action(a,str(d.get("id")),map("action","publish","version",d.get("version")));added++;}return map("added",added,"categories",categories(a),"statistics",statistics(a));}
 @SuppressWarnings("unchecked") @Transactional public Map<String,Object> imports(EhrActor a,Map<String,Object>b){staff(a);require(b.get("documents") instanceof List,422,"需要documents数组");List<?>raw=(List<?>)b.get("documents");require(!raw.isEmpty()&&raw.size()<=500,422,"一次导入1至500篇");Map<String,String> cats=new HashMap<>();for(Map<String,Object>c:categories(a))cats.put(str(c.get("code")),str(c.get("id")));for(Object item:raw){require(item instanceof Map,422,"资料格式错误");Map<String,Object>x=new LinkedHashMap<>((Map<String,Object>)item);if(cats.containsKey(x.get("categoryCode")))x.put("categoryId",cats.get(x.get("categoryCode")));save(a,null,x);}return map("count",raw.size(),"note","全部导入为草稿，未自动发布");}
 public List<Map<String,Object>> export(EhrActor a){staff(a);Map<String,String>codes=new HashMap<>();for(Map<String,Object>c:categories(a))codes.put(str(c.get("id")),str(c.get("code")));List<Map<String,Object>>out=new ArrayList<>();List<Map<String,Object>> rows=db.all("SELECT * FROM a_service_kb_documents WHERE scope_code=? AND data_mode=? AND deleted_at IS NULL ORDER BY category_id,title LIMIT 5001",a.scope,a.mode);require(rows.size()<=5000,413,"导出最多5000篇");for(Map<String,Object>r:rows){Map<String,Object>d=document(r,true);d.put("categoryCode",codes.get(str(d.get("categoryId"))));d.remove("published");out.add(d);}return out;}
}
